arguments.file_text:
namespace UniversityCourseCatalog.Models;

public class Department
{
    public required string Id { get; init; }
    public required string Name { get; init; }
    public required string Description { get; init; }
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public required string Id { get; init; }
    public required string DepartmentId { get; init; }
    public required string Code { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public required int Credits { get; init; }
    public required string Schedule { get; init; }
    public required string Instructor { get; init; }
    public required string InstructorBio { get; init; }
    public bool IsFeatured { get; init; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string Name { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = "";
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, data structures, and the design of software and hardware systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Exploration of abstract structures, quantities, and patterns through rigorous logical reasoning." },
        new() { Id = "phys", Name = "Physics", Description = "Investigation of matter, energy, and the fundamental forces that govern the natural world." },
        new() { Id = "eng", Name = "English", Description = "Analysis and practice of written and spoken language, literature, and critical communication skills." },
        new() { Id = "hist", Name = "History", Description = "Examination of past events, societies, and cultures to understand the forces that shaped the modern world." },
    ];

    private readonly List<Course> _courses =
    [
        // Computer Science
        new() { Id = "cs101", DepartmentId = "cs", Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Instructor = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory computer science. She holds a Ph.D. from MIT and has published extensively on CS education.", IsFeatured = true },
        new() { Id = "cs201", DepartmentId = "cs", Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", Instructor = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm design and competitive programming. He previously worked at Google Research." },
        new() { Id = "cs301", DepartmentId = "cs", Code = "CS 301", Title = "Database Systems", Description = "Principles of database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases. Includes a semester-long project building a real-world application.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Instructor = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory computer science. She holds a Ph.D. from MIT and has published extensively on CS education." },
        new() { Id = "cs401", DepartmentId = "cs", Code = "CS 401", Title = "Machine Learning", Description = "Introduction to machine learning concepts: supervised and unsupervised learning, neural networks, decision trees, and model evaluation. Requires linear algebra and statistics background.", Credits = 4, Schedule = "Tue/Thu 1:00–2:15 PM", Instructor = "Dr. Sarah Kim", InstructorBio = "Dr. Kim is an AI researcher with publications in NeurIPS and ICML. She joined the department after five years at a leading AI startup.", IsFeatured = true },

        // Mathematics
        new() { Id = "math101", DepartmentId = "math", Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Instructor = "Dr. David Park", InstructorBio = "Dr. Park is a mathematician specializing in analysis. He is known for his clear lecture style and has won multiple teaching awards." },
        new() { Id = "math201", DepartmentId = "math", Code = "MATH 201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications. Essential for computer science, physics, and engineering students.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", Instructor = "Dr. Emily Russo", InstructorBio = "Dr. Russo's research focuses on numerical linear algebra and scientific computing. She consults for NASA on trajectory optimization.", IsFeatured = true },
        new() { Id = "math301", DepartmentId = "math", Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis. Applications to data science and research methods.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", Instructor = "Dr. David Park", InstructorBio = "Dr. Park is a mathematician specializing in analysis. He is known for his clear lecture style and has won multiple teaching awards." },

        // Physics
        new() { Id = "phys101", DepartmentId = "phys", Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Algebra-based introduction suitable for life science majors and general education.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Instructor = "Dr. James Okafor", InstructorBio = "Dr. Okafor is an experimental physicist who worked at CERN before joining the university. He brings real-world research into the classroom." },
        new() { Id = "phys201", DepartmentId = "phys", Code = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Calculus-based treatment with laboratory component.", Credits = 4, Schedule = "Tue/Thu 2:00–3:15 PM", Instructor = "Dr. James Okafor", InstructorBio = "Dr. Okafor is an experimental physicist who worked at CERN before joining the university. He brings real-world research into the classroom.", IsFeatured = true },
        new() { Id = "phys301", DepartmentId = "phys", Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, hydrogen atom, spin, and the postulates of quantum mechanics.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", Instructor = "Dr. Lisa Tanaka", InstructorBio = "Dr. Tanaka is a theoretical physicist whose research explores quantum information theory. She has authored a popular textbook on the subject." },

        // English
        new() { Id = "eng101", DepartmentId = "eng", Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop skills in academic writing, argumentation, and critical reading. Emphasis on clarity, evidence-based reasoning, and revision.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Instructor = "Prof. Karen Walsh", InstructorBio = "Prof. Walsh is an award-winning author and writing instructor. She has mentored hundreds of students in developing their writing voice." },
        new() { Id = "eng201", DepartmentId = "eng", Code = "ENG 201", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Authors include Hawthorne, Whitman, Dickinson, Fitzgerald, Morrison, and others.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", Instructor = "Dr. Marcus Johnson", InstructorBio = "Dr. Johnson is a literary scholar specializing in African American literature. His latest book examines narrative identity in contemporary fiction." },

        // History
