{"file_text": "@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p class="text-muted">Submit your enrollment request using the form below.</p>

@if (Submitted)
{
    var selectedCourse = CatalogService.GetCourse(Model.CourseId);
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.Name</strong> (ID: @Model.StudentId). Your enrollment request for
            <strong>@selectedCourse?.Code — @selectedCourse?.Title</strong> has been received.</p>
        <hr />
        <p class="mb-0">You will receive a confirmation via your university email.</p>
    </div>
    <a href="/courses" class="btn btn-primary">Browse More Courses</a>
}
else
{
    <div class="row">
        <div class="col-md-8 col-lg-6">
            <EditForm Model="Model" FormName="enrollment" method="post" OnValidSubmit="HandleSubmit">
                <DataAnnotationsValidator />
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="name" class="form-label">Full Name</label>
                    <InputText id="name" @bind-Value="Model.Name" class="form-control" />
                    <ValidationMessage For="() => Model.Name" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. STU-12345" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                        <option value="">— Select a course —</option>
                        @foreach (var course in CatalogService.GetAllCourses())
                        {
                            <option value="@course.Id">@course.Code — @course.Title</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "course")]
    public string? PreselectedCourse { get; set; }

    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (!Submitted && !string.IsNullOrEmpty(PreselectedCourse) && string.IsNullOrEmpty(Model.CourseId))
        {
            Model.CourseId = PreselectedCourse;
        }
    }

    private void HandleSubmit()
    {
        Submitted = true;
    }
}
